do $$begin if inet_server_addr()<>'127.0.0.1'::inet or inet_server_port()<>55498 or current_database()<>'factory_lean_quality_local' then raise exception 'Disposable operational UX only';end if;end$$;
create schema if not exists ux_test;
create table if not exists ux_test.checks(label text);
create or replace function ux_test.ok(b boolean,l text)returns void language plpgsql as $$begin if b is distinct from true then raise exception 'FAIL %',l;end if;insert into ux_test.checks values(l);end$$;
create table if not exists ux_test.quality_context(x jsonb,output uuid);
do $$declare x jsonb;f uuid;r jsonb;h private.manufactured_outputs;p jsonb;a jsonb;b jsonb;key uuid:=gen_random_uuid();begin
 select t.x into x from output2_test.fixture t;f:=(x->>'factory')::uuid;
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 r:=public.record_manufactured_output(f,output2_test.payload(x,909),gen_random_uuid());
 select * into h from private.manufactured_outputs where entry_id=(r->>'entry_id')::uuid;
 insert into ux_test.quality_context values(x,h.id);
 p:=jsonb_build_object('groups',(select jsonb_agg(g||jsonb_build_object('released',g->>'quantity'))from jsonb_array_elements(h.recorded_groups)g),'rejected','0','total','909','reason','Inspection matches recording');
 a:=public.manufactured_output_command(f,'QUALITY',h.id,p,1,key);
 perform ux_test.ok(a->>'rejected'='0' and a->>'material_difference'='false','matching inspection saved with immutable evidence');
 perform ux_test.ok(not exists(select 1 from jsonb_array_elements(public.manufactured_output_read(f,'notifications')->'rows')v where v->>'id'=h.id::text),'matching inspection no Production notification');
 perform ux_test.ok(not exists(select 1 from jsonb_array_elements(public.manufactured_output_read(f,'quality')->'rows')v where v->>'id'=h.id::text),'completed inspection leaves pending queue');
 perform ux_test.ok(exists(select 1 from jsonb_array_elements(public.manufactured_output_read(f,'quality',h.entry_id)->'rows')v where v->>'id'=h.id::text),'historical exact decision still available');
 perform ux_test.ok(public.manufactured_output_command(f,'QUALITY',h.id,p,1,key)=a,'matching retry exact same receipt');
 p:=jsonb_build_object('groups',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'quantity','907','released','907','missing_operations','[]'::jsonb)),'total','909','rejected','2','reason','Two meters damaged during inspection');
 a:=public.manufactured_output_command(f,'QUALITY',h.id,p,2,gen_random_uuid());
 perform ux_test.ok(a#>>'{groups,0,quantity}'='907' and a->>'material_difference'='true','909 total minus two rejected gives 907 finished');
 p:=jsonb_build_object('groups',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'quantity','903','released','903','missing_operations','[]'::jsonb),jsonb_build_object('id',gen_random_uuid(),'quantity','4','released','4','missing_operations',jsonb_build_array(x->>'step1'))),'total','909','rejected','2','reason','Four meters need final operation');
 a:=public.manufactured_output_command(f,'QUALITY',h.id,p,3,gen_random_uuid());
 perform ux_test.ok(exists(select 1 from jsonb_array_elements(a->'groups')g where g->>'quantity'='903' and jsonb_array_length(g->'missing_operations')=0),'909 minus two rejected and four unfinished gives 903 finished');
 perform ux_test.ok(exists(select 1 from jsonb_array_elements(public.manufactured_output_read(f,'notifications')->'rows')v where v->>'id'=h.id::text and v->>'unread'='true'),'material difference visible as informational notification');
 perform ux_test.ok(not exists(select 1 from public.finished_goods_movements where factory_id=f),'Quality approval never credits stock');
 perform ux_test.ok((select effective_good=909 from public.production_entries where id=h.entry_id),'original technician record immutable');
 -- Corrected measured total is separately audited; source declaration never overwritten.
 p:=jsonb_build_object('groups',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'quantity','908','released','908','missing_operations','[]'::jsonb)),'total','910','rejected','2','reason','Recount confirmed total length of 910 meters');
 a:=public.manufactured_output_command(f,'QUALITY',h.id,p,4,gen_random_uuid());
 perform ux_test.ok(a->>'total'='910' and (select quantity=909 from private.manufactured_outputs where id=h.id),'corrected total distinct from original source');
 perform late_test.fails(format('select public.manufactured_output_command(%L,%L,%L,%L,5,%L)',f,'QUALITY',h.id,p||'{"total":"900"}',gen_random_uuid()),'output_conservation');
 perform late_test.fails(format('select public.manufactured_output_command(%L,%L,%L,%L,4,%L)',f,'QUALITY',h.id,p,gen_random_uuid()),'output_revision');
 perform set_config('request.jwt.claim.sub',x->>'viewer',false);
 perform late_test.fails(format('select public.manufactured_output_command(%L,%L,%L,%L,5,%L)',f,'QUALITY',h.id,p,gen_random_uuid()),'permission_denied');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform late_test.fails(format('select public.manufactured_output_command(%L,%L,%L,%L,5,%L)',gen_random_uuid(),'QUALITY',h.id,p,gen_random_uuid()),'permission_denied');
 perform ux_test.ok(not private.output_material_difference('[{"quantity":"3","missing_operations":["b","a"]}]','{"groups":[{"id":"new","quantity":"1","released":"0","missing_operations":["a","b"]},{"quantity":"2","released":"2","missing_operations":["b","a"]}],"rejected":"0"}'),'unordered equivalent groups and release-only changes do not notify');
end$$;
select count(*) quality_checks from ux_test.checks;
